class cpp_function : public function {
public:
    cpp_function() = default;
    cpp_function(std::nullptr_t);
    cpp_function(std::nullptr_t, const is_setter &);
    template <typename Return, typename... Args, typename... Extra>
    cpp_function(Return (*f)(Args...), const Extra &...extra);
    template <typename Func, typename... Extra, typename = detail::enable_if_t<detail::is_lambda<Func>::value>>
    cpp_function(Func &&f, const Extra &...extra);
    template <typename Return, typename Class, typename... Arg, typename... Extra>
    cpp_function(Return (Class::*f)(Arg...), const Extra &...extra);
    template <typename Return, typename Class, typename... Arg, typename... Extra>
    cpp_function(Return (Class::*f)(Arg...) &, const Extra &...extra);
    template <typename Return, typename Class, typename... Arg, typename... Extra>
    cpp_function(Return (Class::*f)(Arg...) const, const Extra &...extra);
    template <typename Return, typename Class, typename... Arg, typename... Extra>
    cpp_function(Return (Class::*f)(Arg...) const &, const Extra &...extra);
    object name() const;
protected:
    struct InitializingFunctionRecordDeleter { void operator()(detail::function_record *rec); };
    using unique_function_record = std::unique_ptr<detail::function_record, InitializingFunctionRecordDeleter>;
    PYBIND11_NOINLINE unique_function_record make_function_record();
    template <typename Func, typename Return, typename... Args, typename... Extra>
    void initialize(Func &&f, Return (*)(Args...), const Extra &...extra);
    class strdup_guard { /* RAII for strdup'ed strings */
    public:
        strdup_guard() = default; strdup_guard(const strdup_guard &) = delete; strdup_guard &operator=(const strdup_guard &) = delete;
        ~strdup_guard(); char *operator()(const char *s); void release();
    private: std::vector<char *> strings; };
    void initialize_generic(unique_function_record &&unique_rec, const char *text, const std::type_info *const *types, size_t args);
    static void destruct(detail::function_record *rec, bool free_strings = true);
    static PyObject *dispatcher(PyObject *self, PyObject *args_in, PyObject *kwargs_in);
    friend void detail::function_record_PyTypeObject_methods::tp_dealloc_impl(PyObject *);
};

class mod_gil_not_used {
