// Generate a random C string (null-terminated) and pass it to the function.
// Requirement: text must be a valid, non-null C string.
std::string in = FUZZ_PARAM_STR();
const char *c_text = in.c_str();

// Invoke target. The function should handle arbitrary bytes (including whitespace).
std::string out = pybind11::detail::replace_newlines_and_squash(c_text);

// Property: result must be trimmed of leading/trailing ASCII whitespace per spec.
// If non-empty, first and last characters cannot be a space.
if (!out.empty()) {
    FUZZ_ASSERT(out.front() != ' ' && out.back() != ' ', "Output must be trimmed of leading/trailing spaces");
}

// Note: It is valid for out to be empty if input is all whitespace; no assertion made there.
// No persistent objects to return.

// Ensure the Python interpreter is initialized for any potential Python API interactions.
::pybind11::scoped_interpreter guard;

// Create a simple translator that never throws and safely ignores the exception.
// This satisfies the requirement that the translator be compatible with
// ExceptionTranslator (std::function<void(std::exception_ptr)>).
pybind11::register_exception_translator([](std::exception_ptr p) {
    if (!p) { return; }
    try {
        std::rethrow_exception(p);
    } catch (const std::exception &) {
        // Intentionally ignore; real translators would set a Python error here.
        // This must not throw.
    } catch (...) {
        // Unknown exception type; also ignore in this harness.
    }
});

// No persistent objects to return.

// Ensure interpreter is running; although local translators are module-local,
// registration itself does not require a specific scope handle here.
::pybind11::scoped_interpreter guard;

pybind11::register_local_exception_translator([](std::exception_ptr p) {
    if (!p) { return; }
    try {
        std::rethrow_exception(p);
    } catch (const std::exception &) {
        // Ignore; a real translator would set a Python error for this module only.
    } catch (...) {
        // Ignore unknown exceptions.
    }
});

// No persistent objects to return.

// Initialize interpreter: required to create Python exception types under a scope.
::pybind11::scoped_interpreter guard;

// Use __main__ as a stable, valid scope; to avoid name clashes across runs, create
// a fresh submodule under __main__ using a randomized short identifier.
pybind11::module_ main_mod = pybind11::module_::import("__main__");
std::string sub_name_raw = FUZZ_PARAM_STR();
// Sanitize to a valid identifier: [A-Za-z_][A-Za-z0-9_]* and limit length.
std::string sub_name;
sub_name.reserve(32);
for (char ch : sub_name_raw) {
    if (sub_name.size() >= 31) break;
    if ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9') || ch == '_') {
        sub_name.push_back(ch);
    } else {
        sub_name.push_back('_');
    }
}
if (sub_name.empty() || (sub_name[0] >= '0' && sub_name[0] <= '9')) sub_name.insert(sub_name.begin(), 'm');
pybind11::module_ scope = main_mod.def_submodule(sub_name.c_str(), "fuzz submodule for exception reg");

// Randomized, valid exception class name under the chosen scope.
std::string exc_name_raw = FUZZ_PARAM_STR();
std::string exc_name;
exc_name.reserve(32);
for (char ch : exc_name_raw) {
    if (exc_name.size() >= 31) break;
    if ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9') || ch == '_') {
        exc_name.push_back(ch);
    } else {
        exc_name.push_back('_');
