// No persistent objects to return.

// Exercise detail::cast_op<T> by constructing a make_caster<int>, loading from a Python int, and invoking cast_op.
// Requirements enforced:
// - Python interpreter must be initialized (use scoped_interpreter guard).
// - Caster must be loaded prior to calling cast_op.
// - T is int, which has a valid type_caster.
try {
    using namespace pybind11;
    ::pybind11::scoped_interpreter guard{};

    int rnd = (int)(*FUZZ_PARAM(unsigned int) % 100000);
    object py_int = reinterpret_borrow<object>(int_(rnd));

    detail::make_caster<int> caster;
    bool ok = caster.load(py_int, true);
    if (!ok) { FUZZ_BAIL(); }

    // Invoke the helper under test
    auto v = detail::cast_op<int>(caster);

    // Property: cast_op result equals py::cast<int>(py_int)
    int via_cast = cast<int>(py_int);
    FUZZ_ASSERT(v == via_cast, "cast_op<int> did not match cast<int>");
} catch (const std::exception &) { FUZZ_BAIL(); }

