    bool res = detail::isinstance_native_enum<E>(py_val, typeid(E));
    FUZZ_ASSERT(res == false, "isinstance_native_enum should be false for unregistered enum and int object");
} catch (const std::exception &) { FUZZ_BAIL(); }

