// Create a fresh Python class object and set a type-hinted attribute name using attr_with_type_hint<T>.
// Enforce that the key is a valid identifier and not pre-existing.
try {
    using namespace pybind11;
    ::pybind11::scoped_interpreter guard{};

    module_ builtins = module_::import("builtins");
    object py_type = builtins.attr("type");

    // Generate a reasonably safe identifier from fuzz data
    std::string raw = FUZZ_PARAM_STR();
    std::string key;
    key.reserve(raw.size());
    for (unsigned char c : raw) {
        if ((c == '_') || (c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')) key.push_back((char)c);
        if (key.size() > 32) break;
    }
    if (key.empty() || (key[0] >= '0' && key[0] <= '9')) key = "fuzz_attr"; // ensure valid identifier starting char

    // Create a new empty class: C = type("C", (), {})
    object ns_dict = reinterpret_borrow<object>(dict());
    object bases = reinterpret_borrow<object>(tuple());
    object cls = py_type("CFuzz", bases, ns_dict);

    // Ensure __annotations__ absent or empty: provide a fresh dict
    cls.attr("__annotations__") = dict();

    // Set the type hint for attribute 'key' using T=int
    auto accessor = cls.attr_with_type_hint<int>(key.c_str());
    // Assign a default value to the attribute via the accessor
    accessor = int_(123);

    // Validate that __annotations__[key] exists
    dict ann = cls.attr("__annotations__");
    bool contains = ann.contains(key.c_str());
    FUZZ_ASSERT(contains, "__annotations__ missing expected key after attr_with_type_hint");
} catch (const std::exception &) { FUZZ_BAIL(); }

