// Call a Python callable using object_api::operator()<policy>(...). Use builtins.len on a list.
try {
    using namespace pybind11;
    ::pybind11::scoped_interpreter guard{};

    module_ builtins = module_::import("builtins");
    object len_fn = builtins.attr("len");

    // Build a Python list with N elements
    size_t n = (size_t)(*FUZZ_PARAM(unsigned int) % 8);
    object list_ctor = builtins.attr("list");
    object lst = list_ctor();
    for (size_t i = 0; i < n; ++i) {
