// Exercise detail::object_or_cast<T> where T is not a pyobject: should cast a C++ value to pybind11::object.
// Requirements enforced:
// - T is a non-pyobject type (int, double) so the non-pyobject overload is selected.
// - Python interpreter must be initialized for C++ -> Python casting.
// - Pass rvalues to satisfy the function's T&& parameter deduction.
try {
    using namespace pybind11;
    ::pybind11::scoped_interpreter guard{};

    // Case 1: int round-trip
    int v = (int)(*FUZZ_PARAM(unsigned int) % 100000);
    object o1 = detail::object_or_cast(std::move(v));
    int back1 = o1.cast<int>();
    FUZZ_ASSERT(back1 == v, "object_or_cast<int> round-trip mismatch");

    // Case 2: double round-trip for additional coverage
    double d = (double)(*FUZZ_PARAM(unsigned int) % 10000) / 17.0;
    object o2 = detail::object_or_cast(std::move(d));
    double back2 = o2.cast<double>();
    FUZZ_ASSERT(back2 == d, "object_or_cast<double> round-trip mismatch");
} catch (const std::exception &) { FUZZ_BAIL(); }

// Generate a random time_t value and a writable std::tm buffer.
// Requirements enforcement:
//  - time must be non-null: we pass &t
//  - buf must be non-null: we pass &tm_buf
//  - The function may return nullptr on failure; we bail out in that case.

// Derive a time_t from a fuzzed 64-bit signed integer to cover wide ranges.
long long raw = *FUZZ_PARAM(long long);
std::time_t t = static_cast<std::time_t>(raw);

// Writable buffer for the result
std::tm tm_buf{}; // zero-initialize for determinism in failure cases

// Call the target function using the real namespace (avoid the macro-qualified name in C++)
std::tm *ret = pybind11::detail::localtime_thread_safe(&t, &tm_buf);

// If conversion failed (platform may return nullptr for out-of-range values), bail.
if (ret == nullptr) { FUZZ_BAIL(); }

// Lightweight sanity checks on returned fields to exercise read paths without asserting
// overly strong invariants across platforms/timezones.
if (ret->tm_wday < 0 || ret->tm_wday > 6) { FUZZ_BAIL(); }
if (ret->tm_yday < 0 || ret->tm_yday > 365) { FUZZ_BAIL(); }

// No persistent objects to return; nothing to output.

// Exercise format_descriptor for std::complex<T> with T in {float,double,long double}.
// No inputs/outputs (pure, returns std::string). Verify minimal invariants: starts with 'Z'.
{
    unsigned int pick = *FUZZ_PARAM(unsigned int) % 3u;
    std::string fmt;
    switch (pick) {
        case 0: fmt = pybind11::format_descriptor<std::complex<float>>::format(); break;
        case 1: fmt = pybind11::format_descriptor<std::complex<double>>::format(); break;
        default: fmt = pybind11::format_descriptor<std::complex<long double>>::format(); break;
    }
